/* ============================================================
   LIVE DEMO: Wafer Defect Classifier (Stage 6)
   A small real CNN (1,673 params before the fix; final architecture
   below) trained on procedurally-generated synthetic wafer maps that
   mimic the 9 defect classes from the wafer-defect-detection case
   study. This is NOT the original 811K-sample production model or
   dataset, those live with the capstone team and aren't available
   here. The weights below are real, and the forward pass below runs
   genuine client-side inference, entirely in the browser, no network
   call, no backend required even after deployment.
   ============================================================ */

/* conv2d, 3x3 kernel, stride 1, "same" padding, ReLU fused in */
function conv2dSame(input, weights, bias) {
  const H = input.length,
    W = input[0].length,
    Cin = input[0][0].length,
    Cout = bias.length;
  const output = new Array(H);
  for (let y = 0; y < H; y++) {
    const row = new Array(W);
    for (let x = 0; x < W; x++) {
      const outVec = new Array(Cout).fill(0);
      for (let ky = -1; ky <= 1; ky++) {
        const iy = y + ky;
        if (iy < 0 || iy >= H) continue;
        const wPlaneY = weights[ky + 1];
        for (let kx = -1; kx <= 1; kx++) {
          const ix = x + kx;
          if (ix < 0 || ix >= W) continue;
          const wPlane = wPlaneY[kx + 1]; // [Cin][Cout]
          const inVec = input[iy][ix]; // [Cin]
          for (let ci = 0; ci < Cin; ci++) {
            const iv = inVec[ci];
            if (iv === 0) continue;
            const wRow = wPlane[ci]; // [Cout]
            for (let co = 0; co < Cout; co++) {
              outVec[co] += iv * wRow[co];
            }
          }
        }
      }
      for (let co = 0; co < Cout; co++) {
        outVec[co] = Math.max(0, outVec[co] + bias[co]);
      }
      row[x] = outVec;
    }
    output[y] = row;
  }
  return output;
}

function maxPool2x2(input) {
  const H = input.length,
    W = input[0].length,
    C = input[0][0].length;
  const outH = Math.floor(H / 2),
    outW = Math.floor(W / 2);
  const output = new Array(outH);
  for (let y = 0; y < outH; y++) {
    const row = new Array(outW);
    for (let x = 0; x < outW; x++) {
      const vec = new Array(C).fill(-Infinity);
      for (let dy = 0; dy < 2; dy++) {
        for (let dx = 0; dx < 2; dx++) {
          const cell = input[y * 2 + dy][x * 2 + dx];
          for (let c = 0; c < C; c++) if (cell[c] > vec[c]) vec[c] = cell[c];
        }
      }
      row[x] = vec;
    }
    output[y] = row;
  }
  return output;
}

/* Flatten in the same (H, W, C) row-major order Keras uses */
function flattenHWC(input) {
  const H = input.length,
    W = input[0].length,
    C = input[0][0].length;
  const out = new Array(H * W * C);
  let i = 0;
  for (let y = 0; y < H; y++)
    for (let x = 0; x < W; x++) for (let c = 0; c < C; c++) out[i++] = input[y][x][c];
  return out;
}

function dense(vec, weights, bias, activation) {
  const outDim = bias.length;
  const out = new Array(outDim);
  for (let o = 0; o < outDim; o++) {
    let sum = bias[o];
    for (let i = 0; i < vec.length; i++) sum += vec[i] * weights[i][o];
    out[o] = sum;
  }
  if (activation === "relu") return out.map((v) => Math.max(0, v));
  if (activation === "softmax") {
    const max = Math.max(...out);
    const exps = out.map((v) => Math.exp(v - max));
    const sum = exps.reduce((a, b) => a + b, 0);
    return exps.map((v) => v / sum);
  }
  return out;
}

/* grid: 32x32 array of 0/1/2 (background / die / defect) */
function classifyWafer(grid) {
  const input = grid.map((row) => row.map((v) => [v / 2]));
  let x = conv2dSame(input, WAFER_WEIGHTS.conv1.w, WAFER_WEIGHTS.conv1.b);
  x = maxPool2x2(x);
  x = conv2dSame(x, WAFER_WEIGHTS.conv2.w, WAFER_WEIGHTS.conv2.b);
  x = maxPool2x2(x);
  x = conv2dSame(x, WAFER_WEIGHTS.conv3.w, WAFER_WEIGHTS.conv3.b);
  x = maxPool2x2(x);
  const flat = flattenHWC(x);
  const h = dense(flat, WAFER_WEIGHTS.dense1.w, WAFER_WEIGHTS.dense1.b, "relu");
  const probs = dense(h, WAFER_WEIGHTS.dense2.w, WAFER_WEIGHTS.dense2.b, "softmax");
  return WAFER_WEIGHTS.classNames.map((name, i) => ({ name, prob: probs[i] }));
}

/* ---- synthetic sample generators (mirror the Python training generators,
   simplified, for the "Try a pattern" buttons) ---- */
const WSIZE = 32;
const WCENTER = WSIZE / 2;
const WRADIUS = 14.5;

function waferMaskAndDist() {
  const dist = [];
  const mask = [];
  for (let y = 0; y < WSIZE; y++) {
    const drow = [],
      mrow = [];
    for (let x = 0; x < WSIZE; x++) {
      const d = Math.sqrt((x - WCENTER + 0.5) ** 2 + (y - WCENTER + 0.5) ** 2);
      drow.push(d);
      mrow.push(d <= WRADIUS);
    }
    dist.push(drow);
    mask.push(mrow);
  }
  return { dist, mask };
}
const { dist: WDIST, mask: WMASK } = waferMaskAndDist();

function baseWafer() {
  const grid = [];
  for (let y = 0; y < WSIZE; y++) {
    const row = [];
    for (let x = 0; x < WSIZE; x++) row.push(WMASK[y][x] ? 1 : 0);
    grid.push(row);
  }
  return grid;
}

function scatterDefects(grid, regionTest, density) {
  const idx = [];
  for (let y = 0; y < WSIZE; y++)
    for (let x = 0; x < WSIZE; x++) if (regionTest(x, y)) idx.push([y, x]);
  const n = Math.max(1, Math.round(idx.length * density));
  for (let i = idx.length - 1; i > 0 && idx.length - i <= n; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [idx[i], idx[j]] = [idx[j], idx[i]];
  }
  for (let k = 0; k < Math.min(n, idx.length); k++) {
    const [y, x] = idx[k];
    grid[y][x] = 2;
  }
  return grid;
}

const rand = (a, b) => a + Math.random() * (b - a);

const WAFER_GENERATORS = {
  none: () => scatterDefects(baseWafer(), (x, y) => WMASK[y][x], rand(0, 0.02)),
  "Edge-Ring": () =>
    scatterDefects(baseWafer(), (x, y) => WMASK[y][x] && WDIST[y][x] > WRADIUS - rand(2, 3.5), rand(0.55, 0.9)),
  "Edge-Loc": () => {
    const angle = rand(0, Math.PI * 2);
    const cx = WCENTER + Math.cos(angle) * (WRADIUS - 2);
    const cy = WCENTER + Math.sin(angle) * (WRADIUS - 2);
    const r = rand(4, 6);
    return scatterDefects(
      baseWafer(),
      (x, y) => WMASK[y][x] && Math.hypot(x - cx, y - cy) < r,
      rand(0.6, 0.9)
    );
  },
  Center: () => scatterDefects(baseWafer(), (x, y) => WMASK[y][x] && WDIST[y][x] < rand(3.5, 5.5), rand(0.6, 0.95)),
  Loc: () => {
    const r = rand(6.5, WRADIUS - 6.5);
    const angle = rand(0, Math.PI * 2);
    const cx = WCENTER + Math.cos(angle) * r;
    const cy = WCENTER + Math.sin(angle) * r;
    const rr = rand(3, 4.5);
    return scatterDefects(
      baseWafer(),
      (x, y) => WMASK[y][x] && Math.hypot(x - cx, y - cy) < rr,
      rand(0.6, 0.9)
    );
  },
  Scratch: () => {
    const grid = baseWafer();
    const angle = rand(0, Math.PI);
    const length = WRADIUS * 1.7;
    const cx = WCENTER + rand(-4, 4),
      cy = WCENTER + rand(-4, 4);
    for (let t = -length / 2; t <= length / 2; t += length / 200) {
      const x = Math.round(cx + Math.cos(angle) * t + rand(-0.6, 0.6));
      const y = Math.round(cy + Math.sin(angle) * t + rand(-0.6, 0.6));
      if (x >= 0 && x < WSIZE && y >= 0 && y < WSIZE && WMASK[y][x]) grid[y][x] = 2;
    }
    return grid;
  },
  Random: () => scatterDefects(baseWafer(), (x, y) => WMASK[y][x], rand(0.12, 0.28)),
  Donut: () => {
    const r1 = rand(6, 8),
      r2 = r1 + rand(2.5, 4);
    return scatterDefects(
      baseWafer(),
      (x, y) => WMASK[y][x] && WDIST[y][x] > r1 && WDIST[y][x] < r2,
      rand(0.65, 0.95)
    );
  },
  "Near-Full": () => scatterDefects(baseWafer(), (x, y) => WMASK[y][x], rand(0.85, 0.98)),
};

/* ---------------- Wafer-grid signature background ---------------- */
function WaferGrid() {
  const containerRef = useRef(null);
  const [cells, setCells] = useState([]);
  const cols = 28;
  const rows = 16;

  useEffect(() => {
    const total = cols * rows;
    setCells(new Array(total).fill(0));

    const reduce =
      typeof window !== "undefined" &&
      window.matchMedia &&
      window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    if (reduce) return;

    const interval = setInterval(() => {
      setCells((prev) => {
        const next = [...prev];
        const flashes = 3 + Math.floor(Math.random() * 4);
        for (let i = 0; i < flashes; i++) {
          const idx = Math.floor(Math.random() * total);
          next[idx] = Date.now() + Math.random() * 1000;
        }
        return next;
      });
    }, 260);

    return () => clearInterval(interval);
  }, []);

  return (
    <div
      ref={containerRef}
      aria-hidden="true"
      style={{
        position: "absolute",
        inset: 0,
        display: "grid",
        gridTemplateColumns: `repeat(${cols}, 1fr)`,
        gridTemplateRows: `repeat(${rows}, 1fr)`,
        gap: "3px",
        padding: "2px",
        opacity: 0.55,
        maskImage:
          "radial-gradient(ellipse 80% 70% at 50% 40%, black 40%, transparent 85%)",
        WebkitMaskImage:
          "radial-gradient(ellipse 80% 70% at 50% 40%, black 40%, transparent 85%)",
      }}
    >
      {cells.map((flashTime, i) => {
        const active = flashTime && Date.now() - flashTime < 1300;
        const cyanCell = i % 37 === 0;
        return (
          <div
            key={i}
            style={{
              borderRadius: "1px",
              background: active
                ? cyanCell
                  ? "rgba(79, 209, 197, 0.85)"
                  : "rgba(183, 148, 246, 0.9)"
                : "rgba(139, 92, 246, 0.055)",
              boxShadow: active
                ? cyanCell
                  ? "0 0 8px rgba(79,209,197,0.7)"
                  : "0 0 8px rgba(183,148,246,0.65)"
                : "none",
              transition: "background 1.1s ease, box-shadow 1.1s ease",
            }}
          />
        );
      })}
    </div>
  );
}

/* ---------------- Scroll reveal ---------------- */
function usePrefersReducedMotion() {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    if (typeof window === "undefined" || !window.matchMedia) return;
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReduced(mq.matches);
    const handler = (e) => setReduced(e.matches);
    mq.addEventListener ? mq.addEventListener("change", handler) : mq.addListener(handler);
    return () =>
      mq.removeEventListener ? mq.removeEventListener("change", handler) : mq.removeListener(handler);
  }, []);
  return reduced;
}

/* Hook form of the reveal effect below is used instead of a wrapper
   component, so it can be spread onto existing elements directly. */

/* Hook form of the same reveal effect: returns [ref, style] so it can be
   spread onto an existing element's opening tag without needing to touch
   a matching closing tag elsewhere in a large render tree. */
function useRevealStyle() {
  const ref = useRef(null);
  const [visible, setVisible] = useState(false);
  const reduced = usePrefersReducedMotion();

  useEffect(() => {
    if (reduced) {
      setVisible(true);
      return;
    }
    const node = ref.current;
    if (!node) return;
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setVisible(true);
          observer.unobserve(node);
        }
      },
      { threshold: 0.15 }
    );
    observer.observe(node);
    return () => observer.disconnect();
  }, [reduced]);

  const style = {
    opacity: visible ? 1 : 0,
    transform: visible ? "translateY(0)" : "translateY(22px)",
    transition: "opacity 0.7s ease, transform 0.7s cubic-bezier(0.16,1,0.3,1)",
  };

  return [ref, style];
}

