/* ---------------- Command Palette ---------------- */
function CommandPalette({ open, onClose, onNavigate, onOpenProject }) {
  const [query, setQuery] = useState("");
  const [activeIndex, setActiveIndex] = useState(0);
  const inputRef = useRef(null);

  const commands = [
    { id: "hero", label: "Go to top", hint: "Section", run: () => onNavigate("hero") },
    { id: "about", label: "About", hint: "Section", run: () => onNavigate("about") },
    { id: "metrics", label: "Metrics", hint: "Section", run: () => onNavigate("metrics") },
    { id: "projects", label: "Projects", hint: "Section", run: () => onNavigate("projects") },
    { id: "demo", label: "Live Demo", hint: "Section", run: () => onNavigate("demo") },
    { id: "skills", label: "Skills", hint: "Section", run: () => onNavigate("skills") },
    { id: "contact", label: "Contact", hint: "Section", run: () => onNavigate("contact") },
    ...PROJECTS.map((p) => ({
      id: `project-${p.id}`,
      label: p.title,
      hint: `Case study \u00B7 ${p.tag}`,
      run: () => onOpenProject(p),
    })),
    {
      id: "resume",
      label: "Download Resume",
      hint: "PDF",
      run: () => {
        const a = document.createElement("a");
        a.href = RESUME_HREF;
        a.download = "Siva_Madheswaran_Resume.pdf";
        a.click();
      },
    },
  ];

  const filtered = commands.filter((c) => c.label.toLowerCase().includes(query.toLowerCase()));

  useEffect(() => {
    if (open) {
      setQuery("");
      setActiveIndex(0);
      setTimeout(() => inputRef.current && inputRef.current.focus(), 10);
    }
  }, [open]);

  useEffect(() => setActiveIndex(0), [query]);

  useEffect(() => {
    if (!open) return;
    const onKey = (e) => {
      if (e.key === "Escape") {
        onClose();
      } else if (e.key === "ArrowDown") {
        e.preventDefault();
        setActiveIndex((i) => Math.min(i + 1, filtered.length - 1));
      } else if (e.key === "ArrowUp") {
        e.preventDefault();
        setActiveIndex((i) => Math.max(i - 1, 0));
      } else if (e.key === "Enter") {
        e.preventDefault();
        const cmd = filtered[activeIndex];
        if (cmd) {
          cmd.run();
          onClose();
        }
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [open, filtered, activeIndex, onClose]);

  if (!open) return null;

  return (
    <div
      onClick={onClose}
      style={{
        position: "fixed",
        inset: 0,
        zIndex: 200,
        background: "rgba(6,5,10,0.75)",
        backdropFilter: "blur(4px)",
        display: "flex",
        alignItems: "flex-start",
        justifyContent: "center",
        padding: "12vh 20px 20px",
      }}
    >
      <div
        onClick={(e) => e.stopPropagation()}
        style={{
          width: "100%",
          maxWidth: 560,
          background: "#14121F",
          border: "1px solid rgba(139,92,246,0.3)",
          borderRadius: 12,
          boxShadow: "0 20px 60px rgba(0,0,0,0.5)",
          overflow: "hidden",
        }}
      >
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: 10,
            padding: "14px 18px",
            borderBottom: "1px solid rgba(139,92,246,0.16)",
          }}
        >
          <span style={{ color: "#615D78", fontFamily: "'IBM Plex Mono', monospace", fontSize: 14 }}>
            &#8984;K
          </span>
          <input
            ref={inputRef}
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="Jump to a section, a project, or download the resume..."
            style={{
              flex: 1,
              background: "transparent",
              border: "none",
              outline: "none",
              color: "#F1EEFB",
              fontFamily: "'IBM Plex Sans', sans-serif",
              fontSize: 14.5,
            }}
          />
        </div>

        <div style={{ maxHeight: "50vh", overflowY: "auto", padding: 6 }}>
          {filtered.length === 0 && (
            <div
              style={{
                padding: "18px 14px",
                fontFamily: "'IBM Plex Sans', sans-serif",
                fontSize: 13.5,
                color: "#615D78",
              }}
            >
              Nothing matches that. Try a section name or a project title.
            </div>
          )}
          {filtered.map((cmd, i) => (
            <button
              key={cmd.id}
              onClick={() => {
                cmd.run();
                onClose();
              }}
              onMouseEnter={() => setActiveIndex(i)}
              style={{
                display: "flex",
                alignItems: "center",
                justifyContent: "space-between",
                width: "100%",
                textAlign: "left",
                padding: "11px 12px",
                borderRadius: 8,
                border: "none",
                cursor: "pointer",
                background: i === activeIndex ? "rgba(139,92,246,0.16)" : "transparent",
                color: i === activeIndex ? "#F1EEFB" : "#C8C4DC",
                fontFamily: "'IBM Plex Sans', sans-serif",
                fontSize: 14,
              }}
            >
              <span>{cmd.label}</span>
              <span
                style={{
                  fontFamily: "'IBM Plex Mono', monospace",
                  fontSize: 11,
                  color: "#7C7893",
                }}
              >
                {cmd.hint}
              </span>
            </button>
          ))}
        </div>
      </div>
    </div>
  );
}

/* ---------------- Ask about Siva (chatbot) ---------------- */
/* Builds a compact context string from the same data already on the page,
   so the assistant's answers stay grounded in what's actually shown here
   rather than in general knowledge about Siva. */
function buildChatContext() {
  const projectLines = PROJECTS.map(
    (p) =>
      `- ${p.title} (${p.tag}). ${p.team}. My role: ${p.role} Problem: ${p.problem} Results: ${p.results.join(
        " "
      )}`
  ).join("\n");

  const skillLines = SKILLS.map((s) => `${s.category}: ${s.items.join(", ")}`).join("\n");

  return `You are answering questions on behalf of Siva Madheswaran, on his personal portfolio website. Answer in a warm, direct, third-person voice ("Siva did X", "his strongest project is Y"), based only on the information below. If something isn't covered here, say you don't have that detail and suggest the visitor reach out to Siva directly at smadhesw@asu.edu. Keep answers concise, a few sentences unless the question calls for more detail.

ABOUT SIVA
Data Science graduate student at Arizona State University (M.S. Data Science, Analytics and Engineering, GPA 3.77, May 2026). Born and raised in Chennai, Tamil Nadu, India. Completed his B.E. in Computer Science and Engineering in Tirunelveli. Currently on OPT status, actively seeking full-time roles in Data Science, ML Engineering, AI Engineering, and Data Engineering.

WORK EXPERIENCE
Project Engineer Intern, Data Engineering, Wipro, Chennai, India (Mar 2022 - May 2022). Built structured transactional datasets with SQL/PL-SQL, developed modular ETL pipelines with trigger-based audit logging, and performed EDA on transaction data.

SKILLS
${skillLines}

PROJECTS
${projectLines}

CONTACT
Email: smadhesw@asu.edu
LinkedIn: linkedin.com/in/siva-madheswaran-55478a20b
GitHub: github.com/siva-madheswaran`;
}

function ChatBot() {
  const [open, setOpen] = useState(false);
  const [messages, setMessages] = useState([
    {
      role: "assistant",
      text: "Hi, I can answer questions about Siva's projects, skills, and background. What would you like to know?",
    },
  ]);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);
  const scrollRef = useRef(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, open, loading]);

  const send = async () => {
    const text = input.trim();
    if (!text || loading) return;

    const nextMessages = [...messages, { role: "user", text }];
    setMessages(nextMessages);
    setInput("");
    setLoading(true);

    try {
      /* -----------------------------------------------------------------
         This calls the Netlify serverless function at
         netlify/functions/chat.js, which holds the OpenAI API key
         server-side. Set OPENAI_API_KEY as an environment variable in
         your Netlify site settings, never in this frontend file.
         ----------------------------------------------------------------- */
      const response = await fetch("/.netlify/functions/chat", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          system: buildChatContext(),
          messages: nextMessages.map((m) => ({
            role: m.role,
            content: m.text,
          })),
        }),
      });
      const data = await response.json();
      const reply = (data.choices && data.choices[0] && data.choices[0].message
        ? data.choices[0].message.content
        : ""
      ).trim();

      setMessages((prev) => [
        ...prev,
        {
          role: "assistant",
          text: reply || "I couldn't generate a response just now, try asking again in a moment.",
        },
      ]);
    } catch (err) {
      setMessages((prev) => [
        ...prev,
        {
          role: "assistant",
          text: "Something went wrong reaching the assistant. Please try again, or reach Siva directly at smadhesw@asu.edu.",
        },
      ]);
    } finally {
      setLoading(false);
    }
  };

  return (
    <>
      <button
        onClick={() => setOpen((o) => !o)}
        aria-label={open ? "Close chat" : "Ask about Siva"}
        style={{
          position: "fixed",
          bottom: 24,
          right: 24,
          zIndex: 150,
          width: 56,
          height: 56,
          borderRadius: "50%",
          background: "linear-gradient(135deg, #8B5CF6, #4FD1C5)",
          border: "none",
          cursor: "pointer",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          boxShadow: "0 8px 30px rgba(139,92,246,0.45)",
        }}
      >
        {open ? <X size={22} color="#0B0A12" /> : <MessageCircle size={22} color="#0B0A12" />}
      </button>

      {open && (
        <div
          style={{
            position: "fixed",
            bottom: 92,
            right: 24,
            zIndex: 150,
            width: "min(360px, calc(100vw - 40px))",
            height: "min(520px, calc(100vh - 140px))",
            background: "#14121F",
            border: "1px solid rgba(139,92,246,0.28)",
            borderRadius: 14,
            boxShadow: "0 20px 60px rgba(0,0,0,0.5)",
            display: "flex",
            flexDirection: "column",
            overflow: "hidden",
          }}
        >
          <div
            style={{
              padding: "14px 16px",
              borderBottom: "1px solid rgba(139,92,246,0.16)",
              display: "flex",
              alignItems: "center",
              gap: 8,
            }}
          >
            <span
              style={{
                width: 8,
                height: 8,
                borderRadius: "50%",
                background: "#4FD1C5",
                boxShadow: "0 0 6px rgba(79,209,197,0.8)",
              }}
            />
            <span
              style={{
                fontFamily: "'Space Grotesk', sans-serif",
                fontWeight: 600,
                fontSize: 14.5,
                color: "#F1EEFB",
              }}
            >
              Ask about Siva
            </span>
          </div>

          <div
            ref={scrollRef}
            style={{
              flex: 1,
              overflowY: "auto",
              padding: "14px 16px",
              display: "flex",
              flexDirection: "column",
              gap: 12,
            }}
          >
            {messages.map((m, i) => (
              <div
                key={i}
                style={{
                  alignSelf: m.role === "user" ? "flex-end" : "flex-start",
                  maxWidth: "85%",
                  background: m.role === "user" ? "rgba(139,92,246,0.22)" : "rgba(79,209,197,0.08)",
                  border: `1px solid ${
                    m.role === "user" ? "rgba(139,92,246,0.35)" : "rgba(79,209,197,0.2)"
                  }`,
                  borderRadius: 10,
                  padding: "9px 12px",
                  fontFamily: "'IBM Plex Sans', sans-serif",
                  fontSize: 13.5,
                  lineHeight: 1.55,
                  color: "#E7E4F3",
                  whiteSpace: "pre-wrap",
                }}
              >
                {m.text}
              </div>
            ))}
            {loading && (
              <div
                style={{
                  alignSelf: "flex-start",
                  fontFamily: "'IBM Plex Mono', monospace",
                  fontSize: 12,
                  color: "#7C7893",
                }}
              >
                thinking&hellip;
              </div>
            )}
          </div>

          <div
            style={{
              padding: 12,
              borderTop: "1px solid rgba(139,92,246,0.16)",
              display: "flex",
              gap: 8,
            }}
          >
            <input
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && send()}
              placeholder="Ask about a project, skill, or role fit..."
              style={{
                flex: 1,
                background: "#100E1A",
                border: "1px solid rgba(139,92,246,0.2)",
                borderRadius: 8,
                padding: "9px 11px",
                color: "#F1EEFB",
                fontFamily: "'IBM Plex Sans', sans-serif",
                fontSize: 13,
                outline: "none",
              }}
            />
            <button
              onClick={send}
              disabled={loading || !input.trim()}
              aria-label="Send"
              style={{
                width: 38,
                height: 38,
                borderRadius: 8,
                border: "none",
                background: loading || !input.trim() ? "rgba(139,92,246,0.25)" : "#B794F6",
                cursor: loading || !input.trim() ? "default" : "pointer",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                flexShrink: 0,
              }}
            >
              <Send size={16} color="#0B0A12" />
            </button>
          </div>
        </div>
      )}
    </>
  );
}

